const items = $input.all();

return items.map((item) => {
  const customer = item.json;

  const interactions = Array.isArray(customer.interactions)
    ? customer.interactions
    : [];

  const history = interactions.map((i, index) => ({
    number: index + 1,
    date: i.occurred_at || null,
    channel: i.channel || "unknown",
    direction: i.direction || "unknown",
    type: i.type || "unknown",
    subject: i.subject || "",
    message: i.transcript || ""
  }));

  return {
    json: {
      lead_id: customer.lead_id,
      organization_id: customer.organization_id,
      customer_name: [
        customer.first_name,
        customer.last_name
      ].filter(Boolean).join(" "),
      email: customer.email,
      lead_status: customer.lead_status,
      interaction_count: history.length,
      interaction_history: history,
      analysis_instruction:
        "Analyze customer churn risk based on interaction history. Return churn_risk (0-100), health_score (0-100), risk_level (LOW, MEDIUM, HIGH), reason, and recommended_action. Do not invent missing customer information."
    }
  };
});

