const items = $input.all();
const results = [];

for (const item of items) {
  const response = item.json;
  const content = response.choices?.[0]?.message?.content;

  if (!content) {
    throw new Error("Groq did not return AI analysis content");
  }

  const ai = JSON.parse(content);

  const churnRisk = Number(ai.churn_risk);
  const healthScore = Number(ai.health_score);

  if (
    !Number.isFinite(churnRisk) ||
    !Number.isFinite(healthScore) ||
    churnRisk < 0 || churnRisk > 100 ||
    healthScore < 0 || healthScore > 100
  ) {
    throw new Error("Invalid churn risk or health score");
  }

  const riskLevel =
    churnRisk >= 70 ? "HIGH" :
    churnRisk >= 40 ? "MEDIUM" : "LOW";

  const sourceIndex = item.pairedItem?.item;

  if (!Number.isInteger(sourceIndex)) {
    throw new Error(
      "Missing item linkage from Groq AI response"
    );
  }

  const customer = $("Prepare AI Input").all()[sourceIndex]?.json;

  if (!customer?.lead_id || !customer?.organization_id) {
    throw new Error("Missing customer identification");
  }

  results.push({
    json: {
      lead_id: customer.lead_id,
      organization_id: customer.organization_id,
      customer_name: customer.customer_name,
      email: customer.email,
      interaction_count: customer.interaction_count,
      churn_risk: churnRisk,
      health_score: healthScore,
      risk_level: riskLevel,
      reason: String(ai.reason || ""),
      recommended_action: String(ai.recommended_action || ""),
      analyzed_at: new Date().toISOString()
    },
    pairedItem: item.pairedItem
  });
}

return results;

const items = $input.all();

function generateUUID() {
  return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, (c) => {
    const r = Math.floor(Math.random() * 16);
    const v = c === "x" ? r : (r & 3) | 8;
    return v.toString(16);
  });
}

return items.map((item) => {
  const customer = item.json;

  if (customer.risk_level !== "HIGH") {
    throw new Error("This node only handles HIGH churn risk");
  }

  if (!customer.lead_id || !customer.organization_id) {
    throw new Error("Missing lead_id or organization_id");
  }

  const correlationId = generateUUID();

  const responseDeadline = new Date(
    Date.now() + 24 * 60 * 60 * 1000
  ).toISOString();

  return {
    json: {
      ...customer,

      correlation_id: correlationId,
      agent_name: "WF-22-AI-Churn-Monitoring",
      task_status: "pending",
      priority: "urgent",
      action_type: "RETENTION_ESCALATION",

      retention_action: {
        lead_id: customer.lead_id,
        customer_name: customer.customer_name,
        email: customer.email,
        churn_risk: customer.churn_risk,
        health_score: customer.health_score,
        risk_level: customer.risk_level,
        reason: customer.reason,
        recommended_action: customer.recommended_action,
        assigned_team: "Customer Support",
        requires_human_review: true,
        response_deadline: responseDeadline
      }
    }
  };
});

